def canonical_hash(proof):
    return hashlib.sha256(json.dumps(proof,ensure_ascii=False,sort_keys=True,separators=(',',':'),allow_nan=False).encode()).hexdigest()

def attestation_path(path):
    return Path(path).with_name(Path(path).name+'.visibility.json')

def write_attestation(path,proof):
    target=attestation_path(path);temporary=target.with_name(target.name+'.tmp')
    value={'version':1,'proof_sha256':canonical_hash(proof),'png_sha256':proof['sha256']}
    try:
        temporary.write_text(json.dumps(value,sort_keys=True)+'\n');temporary.replace(target)
    finally:
        temporary.unlink(missing_ok=True)

def visibility_valid(proof):
    if isinstance(proof,dict) and type(proof.get('version')) is int and proof['version']==3:
        from .pixel_evidence import proof_valid
        return proof_valid(proof)
    if not isinstance(proof,dict) or proof.get('version')!=2:
        return False
    from .purchase_scope import consumer_scope_valid
    if not consumer_scope_valid(proof):return False
    before,after=proof.get('visibility_before'),proof.get('visibility_after')
    if not isinstance(before,dict) or before!=after or before.get('version')!=1 or before.get('verified') is not True:
        return False
    if not native_receipt_valid(before.get('native_geometry')):
        return False
    fields=before.get('fields');required=proof.get('required_fields')
    if not isinstance(fields,list) or not isinstance(required,list) or len(fields)!=len(required) or not fields:
        return False
    if any(not isinstance(f,dict) for f in fields+required):return False
    if [f.get('role') for f in fields]!=[f.get('role') for f in required] or not {'heading','price'}.issubset(f.get('role') for f in fields):
        return False
    viewport=before.get('viewport',{});scroll=before.get('scroll',{})
    if not isinstance(viewport,dict) or not isinstance(scroll,dict):return False
    if any(type(v) not in (int,float) or not math.isfinite(v) for v in [viewport.get('width'),viewport.get('height'),scroll.get('x'),scroll.get('y')]):
        return False
    if not 0<viewport['height']<=1600 or viewport['width']<=0:
        return False
    region=proof.get('capture_rect',{})
    clip=proof.get('capture_viewport_rect')
    if proof.get('capture_mode')!='viewport' or not isinstance(clip,dict) or not isinstance(region,dict):return False
    try:
        if any(type(clip[k]) not in (int,float) or not math.isfinite(clip[k]) for k in ('x','y','width','height')):return False
        if any(not math.isclose(clip[k]+(scroll[k] if k in ('x','y') else 0),region[k],abs_tol=.001) for k in ('x','y','width','height')):return False
        if clip['x']<0 or clip['y']<0 or clip['width']<=0 or clip['height']<=0 or clip['x']+clip['width']>viewport['width']+.1 or clip['y']+clip['height']>viewport['height']+.1:return False
    except (KeyError,TypeError):return False
    if not isinstance(region,dict) or before.get('url')!=proof.get('url'):return False
    for f in fields:
        if f.get('uncovered') is not True or type(f.get('samples')) is not int or f['samples']<1 or not isinstance(f.get('rects'),list) or not f['rects']:
            return False
        for r in f['rects']:
            try:
                if not isinstance(r,dict):return False
                if any(type(r[k]) not in (int,float) or not math.isfinite(r[k]) for k in ('x','y','width','height')):return False
                if r['width']<=0 or r['height']<=0:return False
                if (r['x']<scroll['x'] or r['y']<scroll['y'] or r['x']+r['width']>scroll['x']+viewport['width']+.1
                    or r['y']+r['height']>scroll['y']+viewport['height']+.1):return False
                if (r['x']<region['x'] or r['y']<region['y'] or r['x']+r['width']>region['x']+region['width']+.1
                    or r['y']+r['height']>region['y']+region['height']+.1):return False
            except (KeyError,TypeError):return False
    return True

def native_receipt_valid(receipt):
    """Validate the optional producer-only binding preserved by sidecar hashing."""
    if receipt is None:return True
    if not isinstance(receipt,dict) or type(receipt.get('version')) is not int or receipt['version']!=1:return False
    if type(receipt.get('document_backend_id')) is not int or receipt['document_backend_id']<=0:return False
    signature=receipt.get('signature_sha256')
    if not isinstance(signature,str) or len(signature)!=64 or any(c not in '0123456789abcdef' for c in signature):return False
    used=receipt.get('used')
    if not isinstance(used,list) or not used:return False
    seen=set()
    for row in used:
        if not isinstance(row,dict) or row.get('part') not in ('::before','::after'):return False
        for key in ('owner_backend_id','pseudo_backend_id'):
            if type(row.get(key)) is not int or row[key]<=0:return False
        identity=(row['owner_backend_id'],row['part'])
        if identity in seen:return False
        seen.add(identity)
        box=row.get('envelope')
        if not isinstance(box,dict) or any(type(box.get(k)) not in (int,float) or not math.isfinite(box[k]) for k in ('left','top','right','bottom')):return False
        if box['right']<=box['left'] or box['bottom']<=box['top']:return False
    return True

def verify_attestation(path,proof):
    try:
        value=json.loads(attestation_path(path).read_text())
        if proof.get('version')==3:
            from .pixel_evidence import proof_valid
            if not proof_valid(proof,path):return False
        return (isinstance(value,dict) and visibility_valid(proof) and value.get('version')==1
          and value.get('proof_sha256')==canonical_hash(proof)
          and value.get('png_sha256')==proof.get('sha256'))
    except (OSError,ValueError,TypeError):
        return False
